// AUTO-GENERATED by Claude Code
// Purpose: hovering a pydantic model's name in a type (render.type_label: the chat rows of a
//          variable, a grid's label, the Variables pane) shows its class as highlighted Python
//          (data-type-html, typeinfo.code_html) with a copy button (data-type-code; the copy
//          itself is panes.js's, as for every .copy-btn). The popover stays while the mouse
//          is on the name or on it, so the button can be reached.
(() => {
  const COPY = "\u{f018f}";
  const COPIED = "\u{f012c}";
  const LEAVE_MS = 200; // time to move from the name onto the popover
  let pop = null;
  let leaving = null;

  const make = () => {
    pop = document.createElement("div");
    pop.className = "type-pop";
    pop.innerHTML = `<pre></pre><button type="button" class="copy-btn mono" title="Copy the class">`
      + `<span class="when-idle">${COPY}</span><span class="when-copied">${COPIED}</span></button>`;
    pop.addEventListener("mouseenter", () => clearTimeout(leaving));
    pop.addEventListener("mouseleave", hideSoon);
    document.body.appendChild(pop);
  };

  const show = (target) => {
    if (!pop) make();
    clearTimeout(leaving);
    // typeinfo.code_html: Pygments' escaped output, only <span class> tags in it
    pop.querySelector("pre").innerHTML = target.getAttribute("data-type-html") || "";
    pop.querySelector(".copy-btn").dataset.copy = target.getAttribute("data-type-code") || "";
    pop.style.display = "block";
    const at = target.getBoundingClientRect();
    const left = Math.min(at.left, window.innerWidth - pop.offsetWidth - 8);
    // under the name, or above it when there is no room below
    const below = at.bottom + 2 + pop.offsetHeight <= window.innerHeight;
    pop.style.left = `${Math.max(8, left)}px`;
    pop.style.top = `${below ? at.bottom + 2 : Math.max(8, at.top - 2 - pop.offsetHeight)}px`;
  };
  const hide = () => {
    clearTimeout(leaving);
    if (pop) pop.style.display = "none";
  };
  function hideSoon() {
    clearTimeout(leaving);
    leaving = setTimeout(hide, LEAVE_MS);
  }

  document.addEventListener("mouseover", (event) => {
    const target = event.target instanceof Element && event.target.closest("[data-type-html]");
    if (target && target.getAttribute("data-type-html")) show(target);
  });
  document.addEventListener("mouseout", (event) => {
    if (event.target instanceof Element && event.target.closest("[data-type-html]")) hideSoon();
  });
  // a scroll elsewhere moves the name from under the popover: drop it
  document.addEventListener("scroll", (event) => {
    if (pop && !pop.contains(event.target)) hide();
  }, true);
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") hide();
  });
})();
